class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        max_distance = 0
        x, y = 0, 0
        changes_used = 0
        n = len(s)
        for i in range(n):
            # Try to change the current character to maximize the Manhattan distance
            if changes_used < k:
                # Try to change the current character to one that increases the Manhattan distance
                # Try all four directions and choose the one that gives the maximum possible distance
                max_possible = 0
                for direction in ['N', 'S', 'E', 'W']:
                    if direction == 'N':
                        new_x, new_y = x, y + 1
                    elif direction == 'S':
                        new_x, new_y = x, y - 1
                    elif direction == 'E':
                        new_x, new_y = x + 1, y
                    elif direction == 'W':
                        new_x, new_y = x - 1, y
                    else:
                        new_x, new_y = x, y
                    current_distance = abs(new_x) + abs(new_y)
                    if current_distance > max_possible:
                        max_possible = current_distance
                if max_possible > (abs(x) + abs(y)):
                    # Change the current character to the one that gives the max possible distance
                    changes_used += 1
