                        y += 1
                    elif s[i] == 'S':
                        y -= 1
                    elif s[i] == 'E':
                        x += 1
                    elif s[i] == 'W':
                        x -= 1
                    else:
                        pass
                else:
                    # Keep the original character
                    if s[i] == 'N':
                        y += 1
                    elif s[i] == 'S':
                        y -= 1
                    elif s[i] == 'E':
                        x += 1
                    elif s[i] == 'W':
