            else:
                # No more changes left, keep the original character
                if s[i] == 'N':
                    y += 1
                elif s[i] == 'S':
                    y -= 1
                elif s[i] == 'E':
                    x += 1
                elif s[i] == 'W':
                    x -= 1
                else:
                    pass
            # Update the maximum distance
            current_distance = abs(x) + abs(y)
            if current_distance > max_distance:
                max_distance = current_distance
